import SwiftUI
import UIKit

/// The pixel look, in one place. Art lives in the app bundle (the sprites are generated by
/// `tools/dotart`), so every lookup goes through `Bundle.main` and degrades to an empty image in
/// previews and tests, where the catalog is absent.
public enum DotTheme {
    /// Screen points per art pixel. Two points is a whole number of device pixels on every iPhone.
    public static let px: CGFloat = 2
}

// MARK: - Palette

/// Mirrors `tools/dotart/palette.py`; names match so art and UI stay in one vocabulary.
public enum DotPalette {
    public static let ink = Color(hex: 0x2b1b2e)
    public static let plum = Color(hex: 0x54304a)
    public static let mauve = Color(hex: 0x8f6384)
    public static let soilDark = Color(hex: 0x5c3a30)
    public static let soil = Color(hex: 0x8a5a3c)
    public static let soilLight = Color(hex: 0xb98352)
    public static let sand = Color(hex: 0xdfb277)
    public static let cream = Color(hex: 0xf5e6c4)
    public static let paper = Color(hex: 0xfffaf0)
    public static let leafDeep = Color(hex: 0x1f4d3b)
    public static let leafDark = Color(hex: 0x2f7d45)
    public static let leaf = Color(hex: 0x58b04a)
    public static let leafLight = Color(hex: 0xa0d85c)
    public static let leafPale = Color(hex: 0xe0f4a4)
    public static let meadow = Color(hex: 0x86c562)
    public static let gold = Color(hex: 0xf4b93a)
    public static let goldLight = Color(hex: 0xffe680)
    public static let goldDark = Color(hex: 0xc47a22)
    public static let orange = Color(hex: 0xf0803a)
    public static let orangeDark = Color(hex: 0xc25a2e)
    public static let red = Color(hex: 0xd94a40)
    public static let redDark = Color(hex: 0x9e2c3c)
    public static let sky = Color(hex: 0x8fd3ee)
    public static let blue = Color(hex: 0x4487cc)
    public static let greyLight = Color(hex: 0xcfccd6)
    public static let grey = Color(hex: 0x9390a1)
    public static let greyDark = Color(hex: 0x5d5870)

    /// Body text on a cream panel.
    public static let text = ink
    /// Secondary text on cream; `greyDark` keeps 6:1 contrast.
    public static let textSecondary = greyDark
}

extension Color {
    init(hex: UInt32) {
        self.init(red: Double((hex >> 16) & 0xff) / 255, green: Double((hex >> 8) & 0xff) / 255,
                  blue: Double(hex & 0xff) / 255)
    }
}

// MARK: - Fonts

/// Galmuri is a bitmap-derived font: it is crisp only at whole multiples of its em (Galmuri11 is
/// 12 px, Galmuri9 is 10 px), so only those sizes exist. Fixed sizes on purpose: Dynamic Type would
/// push the glyphs onto half pixels.
public enum DotFont {
    /// Galmuri9, 10 pt: captions and dense chips.
    case caption
    /// Galmuri11, 12 pt.
    case body
    /// Galmuri11 Bold, 12 pt.
    case bold
    /// Galmuri11 Bold, 24 pt: sheet titles and big numbers.
    case title

    var name: String {
        switch self {
        case .caption: "Galmuri9-Regular"
        case .body: "Galmuri11-Regular"
        case .bold, .title: "Galmuri11-Bold"
        }
    }

    var size: CGFloat {
        switch self {
        case .caption: 10
        case .body, .bold: 12
        case .title: 24
        }
    }
}

public extension Font {
    static func dot(_ font: DotFont) -> Font { .custom(font.name, fixedSize: font.size) }
}

public extension View {
    /// Pixel font, colour and the one-pixel ink drop that keeps light text readable on any panel.
    func dotText(_ font: DotFont = .body, color: Color = DotPalette.text, shadow: Bool = false) -> some View {
        self.font(.dot(font))
            .foregroundStyle(color)
            .shadow(color: shadow ? DotPalette.ink : .clear, radius: 0, x: 0,
                    y: shadow ? (font == .title ? 2 : 1) : 0)
    }
}

// MARK: - Art lookup

@MainActor
enum DotArt {
    private static var images: [String: UIImage] = [:]
    private static var slices: [String: UIImage] = [:]

    /// The 1x asset, whose point size equals its pixel size.
    static func image(_ name: String) -> UIImage? {
        if let cached = images[name] { return cached }
        guard let image = UIImage(named: name, in: .main, compatibleWith: nil) else { return nil }
        images[name] = image
        return image
    }

    /// The asset re-labelled at `px` points per pixel, so a 3 px border is 6 pt on screen and the
    /// stretch region is the only part that scales.
    static func nineSlice(_ name: String) -> UIImage? {
        if let cached = slices[name] { return cached }
        guard let base = image(name), let cg = base.cgImage else { return nil }
        let image = UIImage(cgImage: cg, scale: 1 / DotTheme.px, orientation: .up)
        slices[name] = image
        return image
    }
}

/// A sprite at a whole-number scale, drawn with nearest-neighbour sampling.
public struct DotImage: View {
    let name: String
    let scale: CGFloat
    let label: String?

    public init(_ name: String, scale: Int = 2, label: String? = nil) {
        self.name = name
        self.scale = CGFloat(scale)
        self.label = label
    }

    public var body: some View {
        let size = DotArt.image(name)?.size ?? CGSize(width: 16, height: 16)
        Image(uiImage: DotArt.image(name) ?? UIImage())
            .interpolation(.none)
            .resizable()
            .frame(width: size.width * scale, height: size.height * scale)
            .accessibilityHidden(label == nil)
            .accessibilityLabel(label ?? "")
    }
}

/// 9-slice drawn from a `dot_ui_*` source whose caps are `caps` art pixels.
struct DotNineSlice: View {
    let name: String
    var caps: CGFloat = 8

    var body: some View {
        let inset = caps * DotTheme.px
        Image(uiImage: DotArt.nineSlice(name) ?? UIImage())
            .resizable(capInsets: EdgeInsets(top: inset, leading: inset, bottom: inset, trailing: inset),
                       resizingMode: .stretch)
            .interpolation(.none)
    }
}

// MARK: - Sound hook

/// Effects the UI can ask for. The app maps them onto its player; the default does nothing, so
/// previews stay silent.
public enum DotSoundEffect {
    case tap, purchase, error, missionDone, feverStart
}

private struct DotPlaySoundKey: EnvironmentKey {
    static let defaultValue: @MainActor (DotSoundEffect) -> Void = { _ in }
}

public extension EnvironmentValues {
    var dotPlaySound: @MainActor (DotSoundEffect) -> Void {
        get { self[DotPlaySoundKey.self] }
        set { self[DotPlaySoundKey.self] = newValue }
    }
}
